for(const phase of ['baseline-snapshot','candidate-snapshot','preservation','native-final','practice-current','types','source-build','source-holds','requirements-check','display-check','renderer-check','regional-check'])assert(checks.some(c=>c.phase===phase&&c.exitCode===0),phase);
