const oldPins=JSON.parse(execFileSync('git',['-C',atlas,'show',prepared.head+':content/body-review-display-pins.json'],{encoding:'utf8',maxBuffer:32e6})),newPins=read(atlas+'/content/body-review-display-pins.json');
assert.equal(newPins.pins.length,1104);const changedPins=[];for(const p of newPins.pins){const prev=oldPins.pins.find(b=>b.structureId===p.structureId);assert(prev);if(p.sha256!==prev.sha256)changedPins.push(p.structureId);}assert.deepEqual(changedPins.sort(),read(atlas+'/content/ventricular-landmark-reasoning-pins.json').entries.map(e=>e.identity.id).sort());
const files=[];function walk(root,rel=''){for(const e of fs.readdirSync(root,{withFileTypes:true})){assert(!e.isSymbolicLink());const p=rel?rel+'/'+e.name:e.name;if(e.isDirectory())walk(root+'/'+e.name,p);else files.push({path:p,bytes:fs.statSync(root+'/'+e.name).size,sha256:hash(root+'/'+e.name)});}}walk(atlas+'/dist');files.sort((a,b)=>a.path.localeCompare(b.path));
